        @media(max-width:800px){main{height:auto;grid-template-columns:1fr}#spaceCanvas{height:60vh}aside{display:grid;grid-template-columns:1fr 1fr;gap:8px}}
        </style></head><body><header><h1>SPACEMAP</h1><a href="/indexInternal.es?action=internalWebGL&amp;from=internalStart">Menu</a></header>
        <main id="spacemap"><canvas id="spaceCanvas" aria-label="Space map; click to fly"></canvas><aside><h2 id="mapName">Entering space...</h2>
        <canvas id="minimap" aria-label="Minimap; click to fly"></canvas><dl><dt>Pilot</dt><dd id="pilotName">-</dd><dt>Ship</dt><dd id="shipName">-</dd><dt>Company</dt><dd><span id="factionBadge">-</span></dd><dt>Position</dt><dd id="position">-</dd><dt>Destination</dt><dd id="destination">-</dd><dt>Safe zone</dt><dd id="safeZone">-</dd><dt>Pickup range</dt><dd id="pickupRange">-</dd><dt>Pilots</dt><dd id="pilotCount">-</dd><dt>NPCs</dt><dd id="npcCount">-</dd></dl>
        <label>Hull</label><div class="bar"><span id="hpFill"></span></div><label>Shield</label><div class="bar"><span id="shieldFill"></span></div>
        <dl><dt>Speed</dt><dd id="shipSpeed">-</dd><dt>Shield</dt><dd id="shipShield">-</dd><dt>Laser</dt><dd id="shipLaser">-</dd></dl>
        <p>Configuration <button id="config1" type="button" aria-pressed="true">1</button> <button id="config2" type="button" aria-pressed="false">2</button></p>
        <p><button id="jump" type="button">Jump gate</button> <button id="stationRepair" type="button">Repair at station</button> <a href="/indexInternal.es?action=internalWebGL&amp;from=internalStart">Menu</a></p>
        <p><button id="respawn" type="button" hidden>Repair at home base</button> <button id="respawnHere" type="button" hidden>Repair here (300 uridium)</button> <button id="respawnPortal" type="button" hidden>Repair at nearest gate (200 uridium)</button></p>
        <p><button id="cloak" type="button" aria-pressed="false">Cloak</button> <span id="cloakCooldown" role="status"></span></p>
        <p>Target: <strong id="target">None</strong> <button id="fire" type="button">Fire laser</button> <button id="launcher" type="button">Fire launcher</button> <span id="launcherLoad" role="status"></span> <button id="launcherAuto" type="button" aria-pressed="false">Automatic launcher</button> <button id="rocketAuto" type="button" aria-pressed="false">Automatic rockets</button> <button id="pulse" type="button">Proximity pulse</button></p>
        <p id="announcement" role="status"></p><p id="status" role="status"></p><p id="warning" role="alert"></p><footer>Click the map or minimap to move. Position is synchronized with the local world server.</footer>
        <section id="adminPanel" hidden><h2>In-Game Admin</h2><form id="adminCommandForm"><label for="adminCommand">Slash command</label><input id="adminCommand" maxlength="1024" placeholder="/help"><button type="submit">Run</button></form><pre id="adminResult" role="status"></pre><h2>Runtime Variables Tweaker</h2><form id="adminVariableForm"><select id="adminVariable" aria-label="Runtime variable"></select><input id="adminValue" aria-label="New value"><label for="adminReason">Reason for change or rollback</label><input id="adminReason" maxlength="256" required aria-label="Reason"><button type="submit">Set variable</button></form><h2>Variable Change History</h2><button id="adminRefresh" type="button">Refresh history</button><ol id="adminHistory"></ol><button id="adminMore" type="button" hidden>Load more</button></section>
        </aside></main><script>
        (() => {
          if(navigator.userAgent.includes('Unity Client')){for(const a of document.querySelectorAll('a[href*="action=internalWebGL"]'))a.href=a.getAttribute('href').replace('action=internalWebGL','action=internalMenu');}
          const canvas=document.getElementById('spaceCanvas'), mini=document.getElementById('minimap');
          const ctx=canvas.getContext('2d'), mctx=mini.getContext('2d');
          let state=null, busy=false, jumpPending=false, firePending=false, launcherPending=false, pulsePending=false, cloakPending=false, pendingMoves=0, pendingTargets=0, pendingConfigs=0, pendingBox=null, targetId=null, mapEpoch=0, configEpoch=0, moveSequence=0, queuedMove=null, queuedTarget=null, queuedConfig=null;
          const text=(id,value)=>document.getElementById(id).textContent=value;
          async function request(path, method='GET', body){
            const response=await fetch('/spacemap/world/'+path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});
            if(!response.ok){if(response.status===409){const conflict=await response.json();const messages={map_lease_changed:'Map ownership changed. Try again.',map_changed:'Map changed. Choose a new destination.',move_changed:'Destination changed in another client. Choose it again.',distant:'Target out of laser range. Move closer.',destroyed_pilot:'Ship destroyed. Repair at home base.'};const error=new Error(messages[conflict.status]||conflict.status||('Configuration ready in '+Math.ceil(conflict.cooldownRemainingMs/1000)+'s.'));error.status=conflict.status;throw error;}throw new Error(response.status===401?'Session expired. Return to the menu and sign in.':'World request failed ('+response.status+').');}
            return response.json();
          }
          async function adminRequest(path,method='GET',body){
            const response=await fetch('/spacemap/world/admin/'+path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});
            const result=await response.json();if(!response.ok){const error=new Error(result.error||'Admin request failed ('+response.status+').');error.status=response.status;throw error;}return result;
          }
          let historyBefore=null;
          async function adminHistory(more=false){if(!more)historyBefore=null;const rows=await adminRequest('vars/history?limit=20'+(historyBefore?'&beforeChangeId='+historyBefore:'')),list=document.getElementById('adminHistory');if(!more)list.replaceChildren();for(const row of rows){const item=document.createElement('li'),label=document.createElement('span'),button=document.createElement('button');label.textContent='#'+row.changeId+' '+row.variableKey+' '+row.previousValue+' → '+row.newValue+' ('+row.surface+') by '+row.changedBy+' on '+row.nodeId+' · '+row.reason+' · '+new Date(row.changedAtUtc).toLocaleString()+' ';button.type='button';button.textContent='Rollback';button.addEventListener('click',async()=>{const reason=document.getElementById('adminReason').value.trim();if(!reason){text('adminResult','Enter a reason before rolling back.');return;}try{await adminRequest('vars/rollback','POST',{changeId:row.changeId,reason});await Promise.all([adminVariables(),adminHistory()]);await refresh();}catch(e){if(e.status===409){try{await Promise.all([adminVariables(),adminHistory()]);await refresh();}catch{}}text('adminResult',e.message);}});item.append(label,button);list.append(item);}if(rows.length)historyBefore=rows[rows.length-1].changeId;document.getElementById('adminMore').hidden=rows.length<20;}
          async function adminVariables(){const rows=await adminRequest('vars'),select=document.getElementById('adminVariable');select.replaceChildren();for(const row of rows){const option=document.createElement('option');option.value=row.key;option.textContent=row.key+' ('+row.currentValue+')';option.dataset.value=row.currentValue;select.append(option);}select.dispatchEvent(new Event('change'));}
          async function runAdmin(command){const result=await adminRequest('command','POST',{text:command});text('adminResult',JSON.stringify(result.data,null,2));await Promise.all([adminVariables(),adminHistory()]);await refresh();}
          document.getElementById('adminCommandForm').addEventListener('submit',async e=>{e.preventDefault();try{await runAdmin(document.getElementById('adminCommand').value);}catch(error){text('adminResult',error.message);}});
          document.getElementById('adminVariable').addEventListener('change',e=>{document.getElementById('adminValue').value=e.target.selectedOptions[0]?.dataset.value||'';});
          document.getElementById('adminVariableForm').addEventListener('submit',async e=>{e.preventDefault();const reason=document.getElementById('adminReason').value.trim();if(!reason){text('adminResult','Enter a reason before changing a variable.');return;}try{await runAdmin('/var set '+document.getElementById('adminVariable').value+' '+JSON.stringify(document.getElementById('adminValue').value)+' '+JSON.stringify(reason));}catch(error){text('adminResult',error.message);}});
          document.getElementById('adminRefresh').addEventListener('click',()=>adminHistory().catch(e=>text('adminResult',e.message)));
          document.getElementById('adminMore').addEventListener('click',()=>adminHistory(true).catch(e=>text('adminResult',e.message)));
          function size(c){const r=c.getBoundingClientRect(),d=window.devicePixelRatio||1,w=Math.max(1,Math.round(r.width*d)),h=Math.max(1,Math.round(r.height*d));if(c.width!==w||c.height!==h){c.width=w;c.height=h;}return {w,h};}
          function drawMap(c,g,small){
            const {w,h}=size(c),map=state.map,p=state.pilot,sx=w/map.width,sy=h/map.height;
            if(!small)text('pickupRange',(state.collectionRadius??180)+' units');
            g.clearRect(0,0,w,h);g.fillStyle='#061225';g.fillRect(0,0,w,h);
            g.strokeStyle='#173449';g.lineWidth=1;for(let x=0;x<w;x+=w/10){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke();}for(let y=0;y<h;y+=h/7){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke();}
            g.fillStyle='#a4b7ca';for(let i=0;i<90;i++){const x=((i*7411+1777)%map.width)*sx,y=((i*3191+953)%map.height)*sy;g.fillRect(x,y,small?1:2,small?1:2);}
            const station=map.station;g.strokeStyle='#337b96';g.beginPath();g.arc(station.x*sx,station.y*sy,Math.max(3,station.peaceRadius*Math.min(sx,sy)),0,Math.PI*2);g.stroke();
            g.fillStyle='#85dce4';g.beginPath();g.arc(station.x*sx,station.y*sy,small?3:9,0,Math.PI*2);g.fill();if(!small){g.font='13px system-ui';g.fillText('Home base',station.x*sx+14,station.y*sy);}
            for(const gate of map.portals){g.strokeStyle='#b17be5';g.lineWidth=small?2:4;g.beginPath();g.arc(gate.x*sx,gate.y*sy,small?4:13,0,Math.PI*2);g.stroke();if(!small){g.fillStyle='#d4b8ff';g.font='13px system-ui';g.fillText('Gate '+gate.destinationMapId,gate.x*sx+16,gate.y*sy);}}
            for(const box of state.boxes||[]){g.fillStyle=box.kind==='ore'?'#87dfe0':'#f7c759';g.beginPath();g.arc(box.x*sx,box.y*sy,small?2:7,0,Math.PI*2);g.fill();if(!small){g.font='12px system-ui';g.fillText(box.kind==='ore'?box.assetId:'Bonus',box.x*sx+10,box.y*sy-8);}}
            for(const npc of state.npcs||[]){const nx=npc.x*sx,ny=npc.y*sy;g.fillStyle=npc.kind==='Streuner'?'#f58465':npc.kind==='Lordakia'?'#d970d4':'#cf4c60';g.beginPath();g.moveTo(nx,ny-(small?3:11));g.lineTo(nx+(small?3:11),ny+(small?3:9));g.lineTo(nx-(small?3:11),ny+(small?3:9));g.closePath();g.fill();if(npc.id===targetId){g.strokeStyle='#ffe678';g.lineWidth=2;g.beginPath();g.arc(nx,ny,small?6:18,0,Math.PI*2);g.stroke();}if(!small){g.font='12px system-ui';g.fillText(npc.kind,nx+14,ny-10);}}
            for(const other of state.pilots||[]){if(other.id===p.id)continue;const ox=other.x*sx,oy=other.y*sy;g.fillStyle='#65c8f5';g.beginPath();g.moveTo(ox,oy-(small?4:13));g.lineTo(ox+(small?4:10),oy+(small?4:9));g.lineTo(ox-(small?4:10),oy+(small?4:9));g.closePath();g.fill();if(!small){g.font='12px system-ui';g.fillText(other.name,ox+13,oy-10);}}
            if(p.targetX!==p.x||p.targetY!==p.y){g.strokeStyle='#49aece';g.setLineDash([5,5]);g.beginPath();g.moveTo(p.x*sx,p.y*sy);g.lineTo(p.targetX*sx,p.targetY*sy);g.stroke();g.setLineDash([]);}
            for(const companion of p.companions){const cx=companion.x*sx,cy=companion.y*sy;g.fillStyle=companion.kind==='pet'?'#7eebbd':companion.itemId==='drone_iris'?'#b9a2ff':'#9ac3dd';g.beginPath();if(companion.kind==='pet'){g.arc(cx,cy,small?2:6,0,Math.PI*2);}else{g.moveTo(cx,cy-(small?2:6));g.lineTo(cx+(small?2:6),cy);g.lineTo(cx,cy+(small?2:6));g.lineTo(cx-(small?2:6),cy);g.closePath();}g.fill();}
            const x=p.x*sx,y=p.y*sy;g.save();g.translate(x,y);g.fillStyle='#f7d774';g.strokeStyle='#ffe7a2';g.beginPath();g.moveTo(0,small?-5:-17);g.lineTo(small?5:13,small?5:12);g.lineTo(0,small?2:5);g.lineTo(small?-5:-13,small?5:12);g.closePath();g.fill();g.stroke();g.restore();
            if(!small){g.fillStyle='#f6edcf';g.font='bold 15px system-ui';g.textAlign='center';g.fillText(p.name,x,y+32);g.textAlign='start';}
          }
          function render(){if(!state)return;const cloakWait=state.pilot.cloakCooldownRemainingMs||0;text('cloakCooldown',cloakWait>0?'Ready in '+Math.ceil(cloakWait/1000)+'s':'');const p=state.pilot,station=state.map.station,inside=Math.hypot(p.x-station.x,p.y-station.y)<=station.peaceRadius;text('mapName','Map '+state.map.name);text('pilotName',p.name);text('shipName',p.shipId==='ship_pusat-plus'?'Pusat Plus':p.shipId==='ship_phoenix'?'Phoenix':p.shipId);text('factionBadge',p.company.toUpperCase());text('position',p.x+' / '+p.y);text('destination',p.targetX+' / '+p.targetY);text('safeZone',inside?'Protected':'Outside (radius '+station.peaceRadius+')');text('pilotCount',(state.pilots||[]).filter(other=>other.id!==p.id).length+' nearby');text('npcCount',(state.npcs||[]).length+' visible');text('shipSpeed',p.speed);text('shipShield',p.shield+' / '+p.maxShield);text('shipLaser',p.laserDamage);text('announcement',state.announcement?.message||'');text('warning',p.radiationWarning?'Radiation boundary: destination was clamped.':'');const selected=(state.npcs||[]).find(n=>n.id===targetId);if(!selected)targetId=null;text('target',selected?selected.kind+' · '+selected.hp+'/'+selected.maxHp+' HP · '+selected.shield+'/'+selected.maxShield+' shield':'None');document.getElementById('hpFill').style.width=(p.maxHp?100*p.hp/p.maxHp:0)+'%';document.getElementById('shieldFill').style.width=(p.maxShield?100*p.shield/p.maxShield:0)+'%';for(const n of [1,2])document.getElementById('config'+n).setAttribute('aria-pressed',String(p.configuration===n));drawMap(canvas,ctx,false);drawMap(mini,mctx,true);document.getElementById('respawn').hidden=p.hp>0;document.getElementById('respawnHere').hidden=p.hp>0||state.map.id>=101;document.getElementById('respawnPortal').hidden=p.hp>0||state.map.id>=101||!state.map.portals.some(gate=>gate.working);document.getElementById('pulse').disabled=p.hp<=0||state.map.id>=101||inside||state.map.portals.some(gate=>Math.hypot(p.x-gate.x,p.y-gate.y)<=300)||pulsePending;text('launcherLoad',state.launcher?'('+state.launcher.loaded+'/'+state.launcher.capacity+(state.launcher.loaded<state.launcher.capacity?' · next in '+Math.ceil(state.launcher.reloadRemainingMs/1000)+'s':'')+')':'');document.getElementById('launcher').disabled=p.hp<=0||state.map.id>=101||!selected||state.launcher?.loaded===0||launcherPending;document.getElementById('launcherAuto').hidden=state.map.id>=101;document.getElementById('launcherAuto').setAttribute('aria-pressed',String(state.launcher?.autoFire===true));document.getElementById('rocketAuto').hidden=state.map.id>=101;document.getElementById('rocketAuto').setAttribute('aria-pressed',String(state.rocketAuto===true));document.getElementById('cloak').setAttribute('aria-pressed',String(p.cloaked===true));document.getElementById('cloak').disabled=p.hp<=0||cloakPending||(!p.cloaked&&cloakWait>0);}
          function acceptState(next){if(state&&next.map.id!==state.map.id){mapEpoch++;queuedMove=null;queuedTarget=null;queuedConfig=null;pendingBox=null;targetId=null;text('status','Map changed to '+next.map.name);}state=next;render();}
          document.getElementById('launcherAuto').addEventListener('click',async()=>{if(!state||!state.launcher)return;const button=document.getElementById('launcherAuto');button.disabled=true;try{state.launcher=await request('launcher-auto','POST',{enabled:!state.launcher.autoFire});render();}catch(e){text('status',e.message);}finally{button.disabled=false;}});
          document.getElementById('cloak').addEventListener('click',async()=>{if(!state||cloakPending||state.pilot.hp<=0)return;cloakPending=true;render();const epoch=mapEpoch;try{const result=await request('cloak','POST',{active:!state.pilot.cloaked});if(epoch!==mapEpoch)return;state.pilot.cloaked=result.active;render();text('status',result.active?'Cloak active.':'Cloak disabled.');await refresh();}catch(e){if(epoch===mapEpoch)text('status',e.status==='blocked_map'?'Cloak is unavailable on this map.':e.status==='cooldown'?'Cloak is recharging.':e.message);}finally{cloakPending=false;render();}});
          document.getElementById('rocketAuto').addEventListener('click',async()=>{if(!state)return;const button=document.getElementById('rocketAuto');button.disabled=true;try{const result=await request('rocket-auto','POST',{enabled:!state.rocketAuto});state.rocketAuto=result.autoFire;render();}catch(e){text('status',e.message);}finally{button.disabled=false;}});
          async function refresh(){if(busy||pendingMoves)return;busy=true;const epoch=mapEpoch,sequence=moveSequence,config=configEpoch;try{const next=await request('state');if(epoch!==mapEpoch||sequence!==moveSequence||config!==configEpoch||pendingMoves)return;if(state&&next.map.id!==state.map.id){acceptState(next);return;}state=next;if(pendingBox){const box=(state.boxes||[]).find(b=>b.id===pendingBox);if(!box){pendingBox=null;text('status','Bonus box is no longer available.');}else if(Math.hypot(box.x-state.pilot.x,box.y-state.pilot.y)<=(state.collectionRadius??180)){try{const result=await request('collect','POST',{boxId:box.id,mapId:state.map.id});if(epoch!==mapEpoch||sequence!==moveSequence||pendingMoves)return;pendingBox=null;state.boxes=state.boxes.filter(b=>b.id!==box.id);text('status','Collected '+result.reward.amount+' '+result.reward.assetId);}catch(e){if(epoch!==mapEpoch||sequence!==moveSequence||pendingMoves)return;if(e.status==='map_changed'){const latest=await request('state');if(epoch===mapEpoch)acceptState(latest);return;}if(e.status==='distant')text('status','Pickup range changed. Continuing toward box.');else if(e.status==='claimed'||e.status==='missing'){pendingBox=null;text('status','Bonus box is no longer available.');}else throw e;}}}render();}catch(e){if(epoch===mapEpoch&&sequence===moveSequence&&!pendingMoves){text('status',e.message);pendingBox=null;}}finally{busy=false;}}
          async function sendMoves(){pendingMoves=1;try{while(queuedMove){const command=queuedMove;queuedMove=null;try{const next=await request('move','POST',{...command.body,expectedMoveId:state.pilot.moveId});if(command.epoch===mapEpoch&&command.sequence===moveSequence){state=next;render();}else if(command.epoch===mapEpoch&&queuedMove){state=next;}}catch(e){if((e.status==='move_changed'||e.status==='map_changed')&&command.epoch===mapEpoch){try{const latest=await request('state');if(command.epoch===mapEpoch)acceptState(latest);}catch{}}if(command.epoch===mapEpoch&&command.sequence===moveSequence)text('status',e.message);}}}finally{pendingMoves=0;}}
          async function sendTargets(){pendingTargets=1;try{while(queuedTarget){const command=queuedTarget;queuedTarget=null;try{const lock=await request('target','POST',{npcId:command.id,mapId:command.mapId});if(command.epoch===mapEpoch&&command.sequence===moveSequence){targetId=command.id;text('status','Locked '+lock.kind);render();}}catch(e){if(e.status==='map_changed'&&command.epoch===mapEpoch){try{const latest=await request('state');if(command.epoch===mapEpoch)acceptState(latest);}catch{}}if(command.epoch===mapEpoch&&command.sequence===moveSequence)text('status',e.message);}}}finally{pendingTargets=0;}}
          async function refreshAfterPoll(){while(busy)await new Promise(resolve=>setTimeout(resolve,25));await refresh();}
          async function sendConfigs(){pendingConfigs=1;try{while(queuedConfig){const command=queuedConfig;queuedConfig=null;if(command.epoch!==mapEpoch)continue;try{await request('config','POST',{configuration:command.configuration,mapId:command.mapId});configEpoch++;if(command.epoch===mapEpoch)await refreshAfterPoll();}catch(e){configEpoch++;if(command.epoch===mapEpoch){if(e.status==='map_changed'){try{const latest=await request('state');if(command.epoch===mapEpoch)acceptState(latest);}catch{}}else{text('status',e.message);await refreshAfterPoll();}}}}}finally{pendingConfigs=0;}}
          async function move(event,c){if(!state)return;const epoch=mapEpoch,sequence=++moveSequence,r=c.getBoundingClientRect(),x=Math.round(Math.max(0,Math.min(1,(event.clientX-r.left)/r.width))*state.map.width),y=Math.round(Math.max(0,Math.min(1,(event.clientY-r.top)/r.height))*state.map.height);const npc=(state.npcs||[]).find(n=>Math.hypot(n.x-x,n.y-y)<=Math.max(260,15*state.map.width/c.width));if(npc){queuedMove=null;pendingBox=null;queuedTarget={epoch,sequence,id:npc.id,mapId:state.map.id};if(!pendingTargets)await sendTargets();return;}queuedTarget=null;const box=(state.boxes||[]).find(b=>Math.hypot(b.x-x,b.y-y)<=Math.max(250,13*state.map.width/c.width));pendingBox=box?.id||null;queuedMove={epoch,sequence,body:{x:box?.x||x,y:box?.y||y,mapId:state.map.id}};if(!pendingMoves)await sendMoves();}
          canvas.addEventListener('click',e=>move(e,canvas));mini.addEventListener('click',e=>move(e,mini));
          document.getElementById('jump').addEventListener('click',async()=>{if(!state||jumpPending)return;const p=state.pilot,epoch=mapEpoch,gate=state.map.portals.filter(gate=>gate.working).reduce((best,item)=>!best||Math.hypot(item.x-p.x,item.y-p.y)<Math.hypot(best.x-p.x,best.y-p.y)?item:best,null);if(!gate)return;jumpPending=true;const button=document.getElementById('jump');button.disabled=true;try{const destination=await request('jump','POST',{portalId:gate.id,mapId:state.map.id});if(epoch!==mapEpoch)return;mapEpoch++;state=destination;queuedMove=null;queuedTarget=null;pendingBox=null;targetId=null;text('status','Jumped to map '+state.map.name);render();}catch(e){if(epoch!==mapEpoch)return;if(e.status==='map_changed'||e.status==='map_lease_changed'){try{const latest=await request('state');if(epoch===mapEpoch){acceptState(latest);if(epoch===mapEpoch)text('status',e.message);}}catch{}}else text('status',e.message);}finally{jumpPending=false;button.disabled=false;}});
          document.getElementById('stationRepair').addEventListener('click',async()=>{if(!state)return;const button=document.getElementById('stationRepair'),epoch=mapEpoch,mapId=state.map.id;button.disabled=true;try{const next=await request('station-repair','POST',{mapId});if(epoch!==mapEpoch)return;state=next;render();text('status','Station repair checked.');}catch(e){if(epoch===mapEpoch){text('status',e.message);await refresh();}}finally{button.disabled=false;}});
          for(const [id,location,label] of [['respawn','base','home base'],['respawnHere','death','death location'],['respawnPortal','portal','nearest gate']])document.getElementById(id).addEventListener('click',async()=>{if(!state||state.pilot.hp>0)return;const button=document.getElementById(id);button.disabled=true;try{const next=await request('respawn','POST',{location});acceptState(next);text('status','Repaired at '+label+'.');}catch(e){text('status',e.message);await refresh();}finally{button.disabled=false;}});
          document.getElementById('fire').addEventListener('click',async()=>{if(!targetId||firePending)return;firePending=true;const button=document.getElementById('fire');button.disabled=true;const epoch=mapEpoch,sequence=moveSequence,npcId=targetId,mapId=state.map.id;try{const hit=await request('fire','POST',{npcId,mapId});if(epoch!==mapEpoch||sequence!==moveSequence||targetId!==npcId)return;const reward=hit.reward;const earned=reward?[['credits',reward.credits],['uridium',reward.uridium],['XP',reward.experience],['honor',reward.honor]].filter(([,amount])=>amount>0).map(([name,amount])=>amount+' '+name).join(', '):'';text('status',hit.destroyed?'Destroyed '+hit.target.kind+'; earned '+(earned||'no currency')+'.':'Laser hit '+hit.damage);if(hit.destroyed)targetId=null;await refresh();}catch(e){if(e.status==='map_changed'&&epoch===mapEpoch){try{const latest=await request('state');if(epoch===mapEpoch)acceptState(latest);}catch{}}if(epoch===mapEpoch&&sequence===moveSequence&&targetId===npcId)text('status',e.message);}finally{firePending=false;button.disabled=false;}});
          document.getElementById('launcher').addEventListener('click',async()=>{if(!state||document.getElementById('launcher').disabled)return;launcherPending=true;render();const epoch=mapEpoch,sequence=moveSequence,npcId=targetId,mapId=state.map.id;try{const hit=await request('fire','POST',{npcId,mapId,weapon:'launcher'});if(epoch!==mapEpoch||sequence!==moveSequence||targetId!==npcId)return;const reward=hit.reward;const earned=reward?[['credits',reward.credits],['uridium',reward.uridium],['XP',reward.experience],['honor',reward.honor]].filter(([,amount])=>amount>0).map(([name,amount])=>amount+' '+name).join(', '):'';text('status',hit.destroyed?'Destroyed '+hit.target.kind+'; earned '+(earned||'no currency')+'.':'Launcher hit '+hit.damage);if(hit.destroyed)targetId=null;await refresh();}catch(e){if(e.status==='map_changed'&&epoch===mapEpoch){try{const latest=await request('state');if(epoch===mapEpoch)acceptState(latest);}catch{}}if(epoch===mapEpoch&&sequence===moveSequence&&targetId===npcId)text('status',e.status==='reloading'?'Launcher is reloading.':e.message);}finally{launcherPending=false;render();}});
          document.getElementById('pulse').addEventListener('click',async()=>{if(!state||pulsePending||document.getElementById('pulse').disabled)return;pulsePending=true;render();const epoch=mapEpoch,mapId=state.map.id,actionId=sessionStorage.getItem('pulseActionId')||crypto.randomUUID();sessionStorage.setItem('pulseActionId',actionId);try{const result=await request('pulse','POST',{mapId,actionId});sessionStorage.removeItem('pulseActionId');if(epoch!==mapEpoch)return;text('status',result.hits.length?'Pulse hit '+result.hits.length+' nearby NPC'+(result.hits.length===1?'':'s')+'.':'No NPCs in pulse range.');await refresh();}catch(e){if(e.status==='map_changed'&&epoch===mapEpoch){try{const latest=await request('state');if(epoch===mapEpoch)acceptState(latest);}catch{}}if(e.status)sessionStorage.removeItem('pulseActionId');if(epoch===mapEpoch)text('status',e.status==='out_of_ammo'?'Buy pulse charges in the shop.':e.status==='cooldown'?'Pulse is recharging.':e.status==='refunded'?'Unused pulse charge restored; try again.':e.status==='restricted'?'Pulse cannot activate here.':e.message);}finally{pulsePending=false;render();}});
          for(const n of [1,2])document.getElementById('config'+n).addEventListener('click',()=>{if(!state)return;queuedConfig={configuration:n,epoch:mapEpoch,mapId:state.map.id};if(!pendingConfigs)sendConfigs();});
          window.addEventListener('resize',render);request('enter','POST').then(s=>{state=s;render();if(s.pilot.isAdmin){document.getElementById('adminPanel').hidden=false;Promise.all([adminVariables(),adminHistory()]).catch(e=>text('adminResult',e.message));}return refresh();}).catch(e=>text('status',e.message));setInterval(refresh,150);
        })();
        </script></body></html>
        """;
}
